var t={en:`A socket layer now writes to storage without message service checks; a browser can also write directly. The proper persistence edge disappeared.`,ua:`Сокетний шар записує в сховище без перевірок сервісу повідомлень; браузер теж може писати напряму. Належний шлях зберігання зник.`};var r={en:[`Remove users→persist and socket→persist shortcuts.`,`Restore messages→persist route.`,`Explain room membership validation and lost-ack replay.`],ua:[`Прибери users→persist і socket→persist.`,`Віднови messages→persist.`,`Поясни перевірку членства в кімнаті й повтор після втрати підтвердження.`]};var a=[{en:`Client cannot write directly to server storage.`,ua:`Клієнт не записує напряму в серверне сховище.`},{en:`Messages can be acknowledged only under a defined durability rule.`,ua:`Повідомлення підтверджують за визначеним правилом надійності.`}];var o={remove:[`messages->persist`],add:[{from:`users`,to:`persist`,kind:`data`,label:`Intentional defect / Навмисна помилка`},{from:`socket`,to:`persist`,kind:`data`,label:`Intentional defect / Навмисна помилка`}]};var i={scenario:t,tasks:r,checks:a,mutations:o};export{a as checks,i as default,o as mutations,t as scenario,r as tasks};